import{_ as o,C as a,o as i,c as r,ag as n,E as s}from"./chunks/framework.cyF4XceO.js";const y=JSON.parse('{"title":"Concepts","description":"The portability boundary, Form identity, and lifecycle behind Takoform.","frontmatter":{"title":"Concepts","description":"The portability boundary, Form identity, and lifecycle behind Takoform."},"headers":[],"relativePath":"docs/concepts.md","filePath":"docs/concepts.md"}'),c={name:"docs/concepts.md"};function l(d,e,h,p,m,u){const t=a("StatusNote");return i(),r("div",null,[e[0]||(e[0]=n('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>Takoform keeps workload semantics close to the Form and operational concerns close to the host. These three ideas explain most of the Provider surface.</p><h2 id="portability-has-a-boundary" tabindex="-1">Portability has a boundary <a class="header-anchor" href="#portability-has-a-boundary" aria-label="Permalink to &quot;Portability has a boundary&quot;">​</a></h2><p>A Form owns the application-visible shape of one service primitive: execution ABI, consistency, delivery guarantees, update units, and lifecycle. The host owns implementation, placement, capacity, credentials, routing, recovery, catalog, billing, quota, and SLA.</p><p>Portability therefore means moving the same shape between conforming hosts. It does not mean flattening services into a lowest-common-denominator resource. Different semantics require different Forms.</p><h2 id="a-form-is-an-exact-identity" tabindex="-1">A Form is an exact identity <a class="header-anchor" href="#a-form-is-an-exact-identity" aria-label="Permalink to &quot;A Form is an exact identity&quot;">​</a></h2><p>The four-part current model is deliberately explicit:</p><ul><li>the Host API lane is the literal <code>forms.takoform.com/v1</code>;</li><li>a Form carries its own <code>formId</code> and <code>definitionVersion</code>;</li><li>the Core library follows its own SemVer (<code>v1.1.0</code> today); and</li><li>the Provider follows its own Registry SemVer (<code>3.0.0</code> today).</li></ul><p>A family is a discovery grouping, not a version. A package envelope, schema <code>$id</code>, digest, or Provider descriptor is artifact evidence, not a hidden fifth stream.</p><h2 id="resources-form-a-lifecycle-graph" tabindex="-1">Resources form a lifecycle graph <a class="header-anchor" href="#resources-form-a-lifecycle-graph" aria-label="Permalink to &quot;Resources form a lifecycle graph&quot;">​</a></h2><p>Most resources move through a predictable sequence:</p><ol><li><strong>Identity</strong> — name the service shape and its stable UID.</li><li><strong>Revision</strong> — upload or declare immutable bytes and the fields that make a revision.</li><li><strong>Deployment</strong> — choose which revisions receive traffic.</li><li><strong>Attachment</strong> — expose a domain, endpoint, trigger, consumer, or other inward edge.</li></ol><p>The Provider sends validate, prepare, apply, observe, and delete requests with UID, generation, and revision fences. A missing deployment or stale generation is a contract failure to resolve, not a reason to reinterpret a version.</p><h2 id="capability-is-host-owned" tabindex="-1">Capability is host-owned <a class="header-anchor" href="#capability-is-host-owned" aria-label="Permalink to &quot;Capability is host-owned&quot;">​</a></h2><p>Before applying, the Provider reads the host&#39;s Host Support Profile and checks that the exact FormRef is supported. Typed bindings then add capability to a revision. Placement and credentials never move into the Form definition.</p><h2 id="continue-with-the-source-material" tabindex="-1">Continue with the source material <a class="header-anchor" href="#continue-with-the-source-material" aria-label="Permalink to &quot;Continue with the source material&quot;">​</a></h2><p>The <a href="/docs/versions.html">version model</a> is the current compatibility entry point. The old <a href="/spec/">Specification routes</a> remain available as historical source with a banner; they document receipts and withdrawn decisions rather than a live release train.</p>',17)),s(t)])}const b=o(c,[["render",l]]);export{y as __pageData,b as default};
